-- Generated from the repository's deterministic demo fixtures.
-- Regenerate with: npm run supabase:generate-demo
begin;

do $seed$
declare
  demo_user_id uuid;
  demo_store_id uuid;
begin
  select id into strict demo_user_id
  from auth.users
  where lower(email) = lower('kevin@webaanzee.be');

  select membership.store_id into strict demo_store_id
  from public.store_memberships membership
  join public.stores store on store.id = membership.store_id
  where membership.user_id = demo_user_id
    and membership.role = 'owner'
    and membership.status = 'active'
    and store.is_demo = true;

  if exists (
    select 1 from private.demo_seed_runs
    where store_id = demo_store_id
      and seed_name = 'pwayment-retail-demo'
      and seed_version = 1
  ) then
    return;
  end if;

  update public.stores
  set name = 'PWAYMENT Demo Store',
      legal_name = $pwayment_demo$"PWAYMENT"$pwayment_demo$::jsonb #>> '{}',
      vat_number = $pwayment_demo$"BE0123.456.789"$pwayment_demo$::jsonb #>> '{}',
      address_line_1 = $pwayment_demo$"Voorbeeldstraat 1"$pwayment_demo$::jsonb #>> '{}',
      address_line_2 = $pwayment_demo$"9000 Gent"$pwayment_demo$::jsonb #>> '{}',
      phone = $pwayment_demo$"+32 9 000 00 00"$pwayment_demo$::jsonb #>> '{}',
      email = $pwayment_demo$"hallo@pwayment.be"$pwayment_demo$::jsonb #>> '{}',
      website = $pwayment_demo$"www.pwayment.be"$pwayment_demo$::jsonb #>> '{}',
      receipt_footer = $pwayment_demo$"Bedankt voor uw aankoop."$pwayment_demo$::jsonb #>> '{}',
      return_policy = $pwayment_demo$"Retour of omruiling volgens winkelvoorwaarden met origineel ticket."$pwayment_demo$::jsonb #>> '{}',
      is_demo = true
  where id = demo_store_id;

