  insert into public.webshop_settings (
    store_id, settings, is_enabled, subdomain, custom_domain, is_demo
  ) values (
    demo_store_id,
    $pwayment_demo${"isEnabled":true,"shopName":"Pwayment Skate Shop","shopTagline":"De nummer 1 winkel voor skateboards, apparel en accessoires.","subdomain":"pwayment-skateshop","customDomain":"www.pwayment-skateshop.be","domainStatus":"connected","contactEmail":"webshop@pwayment-skateshop.be","contactPhone":"+32 9 234 56 78","seoDescription":"Shop de nieuwste decks, trucks, wielen en streetwear online met snelle levering in België en Nederland.","currency":"EUR (€)","themeStyle":"clean-modern","primaryColor":"#0ea5e9","announcementActive":true,"announcementText":"⚡ GRATIS verzending bij bestellingen vanaf €50 | Vandaag besteld = morgen in huis","heroTitle":"Exclusieve Boards & Urban Culture","heroSubtitle":"Ontdek onze handgeplukte collectie skateboards, sneakers en streetwear in de officiële webshop.","heroImageUrl":"https://images.unsplash.com/photo-1520045892732-304bc3ac5d8e?auto=format&fit=crop&w=1600&q=80","gridColumns":3,"showOutOfStock":true,"showStockCount":true,"unpublishedProductIds":[],"featuredProductIds":["skateboards-decks-street-antwerp-skate-co-popsicle-maple-deck-8-25-8-25-inch","apparel-truien-hoodies-antwerp-skate-co-heavy-logo-hoodie-black-m","components-trucks-axis-hardware-raw-trucks-set-149-149-mm"],"productDescriptions":{"skateboards-decks-street-antwerp-skate-co-popsicle-maple-deck-8-25-8-25-inch":"Hoogwaardig 7-ply Canadees esdoorn skateboarddeck. Perfect voor street en park met sterke pop, betrouwbare concave en een duurzame constructie.","apparel-truien-hoodies-antwerp-skate-co-heavy-logo-hoodie-black-m":"Zware premium hoodie met zachte fleecevoering en een relaxte skatesilhouet. Ontworpen voor dagelijks gebruik, van eerste push tot late sessie.","components-trucks-axis-hardware-raw-trucks-set-149-149-mm":"Solide 149 mm trucks met een voorspelbare turn en stabiele grind. Een betrouwbare keuze voor decks van 8.25 tot 8.5 inch."},"productImages":{"skateboards-decks-street-antwerp-skate-co-popsicle-maple-deck-8-25-8-25-inch":"https://images.unsplash.com/photo-1547447134-cd3f5c716030?auto=format&fit=crop&w=1000&q=82","apparel-truien-hoodies-antwerp-skate-co-heavy-logo-hoodie-black-m":"https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=1000&q=82","components-trucks-axis-hardware-raw-trucks-set-149-149-mm":"https://images.unsplash.com/photo-1520045892732-304bc3ac5d8e?auto=format&fit=crop&w=1000&q=82"},"productVariants":{},"coupons":[{"code":"WELKOM10","discountType":"percent","value":10,"minOrderCents":0,"active":true},{"code":"SKATE5","discountType":"fixed","value":500,"minOrderCents":2500,"active":true}],"webshopMarkupPercent":0,"autoSyncStock":true,"freeShippingThresholdCents":5000,"shippingFeeCents":495,"pickupEnabled":true,"pickupAddress":"Kouter 12, 9000 Gent, België","pickupInstructions":"Haal uw bestelling gratis op in de winkel binnen 2 uur na bevestiging.","paymentMethods":{"bancontact":true,"ideal":true,"creditcard":true,"applepay":true,"klarna":true,"payOnPickup":true},"requireTermsCheckbox":true,"enableOrderNotes":true,"activePlan":"free","instagramUrl":"https://instagram.com/pwayment","facebookUrl":"https://facebook.com/pwayment","orderNotificationEmail":"bestellingen@pwayment-skateshop.be","autoConfirmOrders":true}$pwayment_demo$::jsonb,
